<?php require 'config/db.php';require 'includes/functions.php';require_login();$where='';$uid=(int)user()['id'];
if(is_role('donor'))$where="WHERE (br.requester_id=$uid OR rm.donor_id=$uid)";elseif(is_role('requester'))$where="WHERE br.requester_id=$uid";elseif(is_role('hospital')){$h=$conn->query("SELECT id FROM hospitals WHERE user_id=$uid LIMIT 1")->fetch_assoc();$hid=(int)($h['id']??0);$where="WHERE br.hospital_id=$hid";}
$sql="SELECT DISTINCT br.*,h.name hospital_name FROM blood_requests br LEFT JOIN hospitals h ON h.id=br.hospital_id LEFT JOIN request_matches rm ON rm.request_id=br.id $where ORDER BY br.created_at DESC";$cases=$conn->query($sql);$pageTitle='Case History';include 'includes/header.php';?>
<section class="page-hero"><div class="container"><span class="kicker">Traceable records</span><h1>Complete case history</h1><p>Review emergencies, status changes, matched donors, completion records and timestamps.</p></div></section><section class="section-sm"><div class="container"><div class="history-list"><?php while($r=$cases->fetch_assoc()):?><a class="history-card" href="request-view.php?id=<?=$r['id']?>"><div class="history-blood"><?=e($r['blood_group'])?></div><div><span class="kicker">Case #<?=str_pad($r['id'],5,'0',STR_PAD_LEFT)?></span><h3><?=e($r['patient_name'])?></h3><p><?=e($r['hospital_name']?:$r['address'])?> • <?=date('M d, Y h:i A',strtotime($r['created_at']))?></p></div><div class="history-meta"><span class="priority <?=e($r['priority'])?>"><?=e($r['priority'])?></span><b><?=e(status_label($r['status']))?></b><small><?=$r['units']?> unit(s)</small></div></a><?php endwhile;?></div></div></section><?php include 'includes/footer.php';?>
